import random

def rounds_to_spread(n: int, fanout: int = 3, seed: int = 0) -> int:
    """Push gossip: each informed node tells `fanout` random peers per round."""
    rnd = random.Random(seed)
    informed = {0}                 # node 0 learns that a node joined
    rounds = 0
    while len(informed) < n:
        informed |= {rnd.randrange(n) for _ in informed for _ in range(fanout)}
        rounds += 1
    return rounds

for n in (1_000, 10_000, 100_000):
    print(n, rounds_to_spread(n))  # 8, 10, 13: 100x the nodes, 5 more rounds

def merge(mine: dict, theirs: dict) -> None:
    # entry = (generation, heartbeat): the higher tuple is newer, so it wins.
    # No coordinator: any two nodes that talk end up with the same view.
    for node, state in theirs.items():
        if state > mine.get(node, (0, -1)):
            mine[node] = state
